    return out

@classmethod
def _ctx_before(cls, ordered: list[Block], idx: int, n: int = CTX_NEIGHBORS) -> list[Block]:
    """切片首块**之前**最近的 `n` 个正文块（由远到近返回）。

    ⚠️ 必须跳过页面家具：原先取 `ordered[idx-1]` 是**裸相邻** —— 跨页处那个"上文"
