export function DocBlock({ b, mode, assets, selected, flash, onPick }: {
  b: Block; mode: Mode
  assets?: Map<string, { width?: number; height?: number }>
  selected?: boolean
  flash?: boolean
  onPick?: (blockId: string) => void
}) {
